 assert (select relrowsecurity and relforcerowsecurity from pg_class where oid='public.video_source_uploads'::regclass); assert not has_table_privilege('service_role','public.video_source_uploads','select'); assert not has_table_privilege('authenticated','public.video_source_uploads','insert');
