-- Build one canonical completed product and exercise the RPC-only safe projection.
do $$ declare p public.video_projects;oid uuid;aid uuid;product jsonb;begin
 select * into p from public.video_projects where idempotency_key='prompt-standard';update public.compute_jobs set state='succeeded',terminal_at=now() where id in(p.video_job_id,p.stitch_job_id);update public.video_projects set storage_bucket='video-private',completed_at=now() where id=p.id;
 insert into public.generations(id,user_id,prompt,image_url,lora_used,job_type,body_type,mode,status,negative_prompt,width,height,completed_at,metadata,updated_at) values(p.id,p.owner_id,'prompt',null,null,'video','none','text_to_video','completed','',1920,1080,now(),jsonb_build_object('actual_duration_ms',10000,'fps_millihz',30000,'kind','video','policy_version','1','private_creator_media',true,'requested_duration_seconds',10,'segment_count',2,'target_min_short_edge',1080,'video_project_id',p.id),now());
 insert into public.private_storage_objects(owner_id,storage_class,bucket,object_key,mime_type,size_bytes,sha256,source_reference) values(p.owner_id,'creator_generation','video-private','creator-video-projects/'||p.id||'/final/final.mp4','video/mp4',2000,repeat('f',64),jsonb_build_object('video_project_id',p.id)) returning id into oid;insert into public.generation_assets(generation_id,storage_object_id,owner_id,ordinal,kind) values(p.id,oid,p.owner_id,0,'video') returning id into aid;update public.compute_jobs set result_reference=jsonb_build_object('project_id',p.id,'generation_id',p.id,'asset_ids',jsonb_build_array(aid)) where id=p.stitch_job_id;
 product:=public.creator_video_project_product(p.owner_id,p.id);assert product->>'project_id'=p.id::text and product->'output'->>'id'=aid::text and product->>'motion_strength'='0.4';assert not product ?| array['bucket','object_key','sha256','provider','request_payload'];
end$$;
do $$ begin assert has_function_privilege('service_role','public.creator_video_project_product(uuid,uuid)','execute');assert not has_function_privilege('authenticated','public.creator_video_project_product(uuid,uuid)','execute');assert not has_table_privilege('service_role','public.video_projects','select');end$$;
